// Package templates holds the templ components that render each page.
//
// The *_templ.go files in this package are generated by `go tool templ generate`.
// Edit the .templ sources, never the generated output.
//
// Components take pre-built hrefs and plain strings. Nothing here accepts
// markup, and there is no helper that would let scraped or feed text reach the
// page unescaped: templ escapes every { expression } it renders.
package templates

// FeedLink is one entry in the feed navigation list. Href is built by the
// caller so the whole URL is testable as a single string.
type FeedLink struct {
	Title string
	Href  string
}

// HomeProps is the home page's view model.
type HomeProps struct {
	Feeds []FeedLink
}

// FeedItem is one article row in a feed listing. An empty Href means the feed
// entry had no link, and the title renders as plain text.
type FeedItem struct {
	Title     string
	Href      string
	Published string
}

// FeedProps is the feed page's view model.
type FeedProps struct {
	Title string
	Items []FeedItem
}

// ArticleProps is the article page's view model. An empty FeedHref omits the
// feed breadcrumb entirely.
type ArticleProps struct {
	Title      string
	Paragraphs []string
	SourceURL  string
	FeedTitle  string
	FeedHref   string
}

// ErrorProps is the error page's view model.
type ErrorProps struct {
	Title   string
	Message string
}

// truncate shortens text to max runes and appends an ellipsis. It counts runes,
// not bytes or UTF-16 code units, so it never splits a multi-byte character.
func truncate(text string, max int) string {
	runes := []rune(text)
	if len(runes) <= max {
		return text
	}
	return string(runes[:max]) + "..."
}
